(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.012-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.28)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.15)*8 + Math.cos(sy*0.02-t*0.12)*6;
  const w2y = Math.cos(sy*0.022-t*0.17)*8 + Math.sin(sx*0.019+t*0.2)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.11,2.1,0.65],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8,0.85]
  ];
  let aS=0,iS=0,dif=0,tw=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    dif+=Math.sin(d*f*1.3-t*sp*0.4+0.8)*w*0.5;
    tw+=Math.sin(d*f*0.5+t*sp*0.3-2.0)*w*0.3;
  }
  const n=src.reduce((s,v)=>s+v[4],0);
  const act=aS/n,inh=iS/n,df=dif/n,twv=tw/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    +Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2
    +Math.sin(fx*0.005+fy*0.008+t*0.6)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.07-ang*2+t*0.9))*0.27;
  const cX=fx*0.08,cY=fy*0.08;
  const ci=Math.floor(cX),cj=Math.floor(cY);
  let minD=99,secD=99;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const nx=ci+di,ny=cj+dj;
    const px=nx+Math.sin(nx*12.9898+ny*78.233+t*0.5)*0.4+0.5;
    const py=ny+Math.cos(nx*63.7264+ny*10.873+t*0.4)*0.4+0.5;
    const d=Math.sqrt((cX-px)**2+(cY-py)**2);
    if(d<minD){secD=minD;minD=d;}else if(d<secD)secD=d;
  }
  const voronoi=Math.sin(minD*Math.PI*2)*0.25+Math.sin((secD-minD)*Math.PI*4)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+df*0.4+twv*0.3+voronoi)*2.0);
  const v=reaction*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,85],[18,85,115],[25,130,130],[45,165,120],
    [120,185,90],[200,190,70],[230,160,60],[220,110,65],[190,70,70],
    [140,40,75],[85,25,70],[40,18,60],[5,12,52]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,reaction)*0.3;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*15)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*5)|0)
  ];
}
